const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (line) => {
    const A = parseInt(line.trim(), 10);
    if (isNaN(A)) {
        console.log(0);
        return;
    }

    // If A = 1, there are no solutions since sigma(x) >= 1+x > 1 for x>=1
    if (A === 1) {
        console.log(0);
        return;
    }

    let count = 0;

    // Find all divisors of A
    const divisors = [];
    for (let i = 1; i * i <= A; i++) {
        if (A % i === 0) {
            divisors.push(i);
            if (i !== A / i) {
                divisors.push(A / i);
            }
        }
    }
    divisors.sort((a, b) => a - b);
    const divSet = new Set(divisors);

    // DP to find multiplicative partitions of A into valid sigma(p^k) terms
    // dp[i] = set of minimal primes used to achieve product divisors[i]
    // Actually, we need to count distinct x.
    // We use a map: product_value -> Map<min_prime, count>
    // Or simply an array of maps since we iterate divisors in increasing order.

    // Precompute for each divisor d, the list of (prime, exponent) pairs such that sigma(p^k) = d
    const termOptions = new Map(); // d -> Array<{p, k}>
    for (const d of divisors) {
        if (d === 1) continue; // sigma(p^k) >= 1+p >= 3
        const options = [];
        // k = 1: sigma(p) = p+1 = d => p = d-1
        const p1 = d - 1;
        if (p1 >= 2 && isPrime(p1)) {
            options.push({ p: p1, k: 1 });
        }
        // k >= 2: sigma(p^k) = (p^(k+1)-1)/(p-1) = d
        // p^2 < d => p <= sqrt(d)
        const maxP = Math.floor(Math.sqrt(d));
        for (let p = 2; p <= maxP; p++) {
            if (!isPrime(p)) continue;
            let sum = 1 + p;
            let term = p * p;
            let k = 2;
            while (sum < d) {
                sum += term;
                if (sum === d) {
                    options.push({ p, k });
                    break;
                }
                if (term > (d - sum) * p) break; // overflow/overflow check logic, simple break if term gets too large
                term *= p;
                k++;
                if (k > 40) break; // safety break, 2^40 > 1e12
            }
        }
        if (options.length > 0) {
            termOptions.set(d, options);
        }
    }

    // DP: map from product value to Map<minPrime, count>
    // minPrime is the minimum prime allowed for the *next* factor (primes must be strictly increasing to ensure uniqueness)
    const dp = new Map(); // divisor -> Map<minPrime, count>

    // Base case: product 1, minPrime 2 (smallest prime), count 1
    dp.set(1, new Map([[2, 1]]));

    for (const d of divisors) {
        if (d === 1) continue;
        if (!termOptions.has(d)) continue;

        const options = termOptions.get(d);
        // For each divisor prev_d such that prev_d * d divides A
        // We iterate through existing dp states.
        // To avoid modifying map while iterating, collect updates.
        const updates = []; // [new_product, new_minPrime, count_to_add]

        for (const [prevProd, primeMap] of dp.entries()) {
            if (A % (prevProd * d) !== 0) continue;
            const newProd = prevProd * d;
            for (const [minP, cnt] of primeMap.entries()) {
                for (const opt of options) {
                    if (opt.p >= minP) {
                        updates.push([newProd, opt.p + 1, cnt]);
                    }
                }
            }
        }

        for (const [prod, mp, cnt] of updates) {
            if (!dp.has(prod)) dp.set(prod, new Map());
            const m = dp.get(prod);
            m.set(mp, (m.get(mp) || 0) + cnt);
        }
    }

    // Sum up counts for product A
    if (dp.has(A)) {
        for (const cnt of dp.get(A).values()) {
            count += cnt;
        }
    }

    console.log(count);
});

function isPrime(n) {
    if (n < 2) return false;
    if (n % 2 === 0) return n === 2;
    if (n % 3 === 0) return n === 3;
    const limit = Math.floor(Math.sqrt(n));
    for (let i = 5; i <= limit; i += 6) {
        if (n % i === 0 || n % (i + 2) === 0) return false;
    }
    return true;
}
